118	            return new ResponseEntity<>(HttpStatus.CONFLICT);
119	        }
120	        owner.setMembershipNumber(this.clinicService.findAllOwners().size() + 1);
121	        owner.setCity(resolveCityName(owner.getCity()));
122	        long ownersInCity = this.clinicService.findAllOwners().stream()
123	            .filter(existing -> existing.getCity() != null
124	                && existing.getCity().equalsIgnoreCase(owner.getCity()))
125	            .count();
126	        owner.setCustomerCode(String.format("%s-%04d",
