142	     * @return the city name to store, or {@code null} if {@code city} is {@code null}
143	     */
144	    private String resolveCityName(String city) {
145	        if (city == null) {
146	            return null;
147	        }
148	        return this.clinicService.findAllOwners().stream()
149	            .map(Owner::getCity)
150	            .filter(existing -> existing != null && existing.equalsIgnoreCase(city))
151	            .findFirst()
152	            .orElseGet(() -> toTitleCase(city));
