159	     *
160	     * @param city the city name to title-case
161	     * @return the title-cased city name
162	     */
163	    private static String toTitleCase(String city) {
164	        StringBuilder result = new StringBuilder(city.length());
165	        boolean startOfWord = true;
166	        for (int i = 0; i < city.length(); i++) {
167	            char c = city.charAt(i);
168	            if (Character.isWhitespace(c)) {
169	                startOfWord = true;
170	                result.append(c);
171	            } else {
172	                result.append(startOfWord
173	                    ? Character.toTitleCase(c)
